    // FR-PROXY-022 AC-3: the backend presents an expired self-signed certificate; that it shares its name and key with
    // the valid given certificate does not make its validity period unchecked
    @Test(timeout = 30000)
    public void lp1_anExpiredPresentedSelfSignedCopyOfTheGivenCertificateIsConnectFailed() throws Exception {
        TlsBackend b = backend(presenting(selfKey, expiredSelfCopy));
        mount(Proxy.to("https://localhost:" + b.port()).trustCertificates(renewedSelf));

        assertConnectFailed(get(), b);
