    // FR-PROXY-022 AC-3: the only given certificate, a self-signed one, expires between two connections to the same
    // mount; the second connection gives 502 CONNECT_FAILED (an expired trusted self-signed certificate)
    @Test(timeout = 60000)
    public void lp3b_anExpiredTrustedSelfSignedCertificateIsConnectFailedAfterAnEarlierConnection() throws Exception {
        X509Certificate c = shortLived("short2")[0];
