        mount(Proxy.to("https://localhost:" + b.port()).trustCertificates(c));
        assertReached(get());
        long wait = c.getNotAfter().getTime() - System.currentTimeMillis() + 1500;
        assertTrue("fixture: expires soon, wait " + wait, wait > 0 && wait < 20000);
        Thread.sleep(wait);
        assertConnectFailed(get(), b);
    }

