            }
            System.out.println("LP first " + first.getProtocol() + " created " + first.getCreationTime());
        }
        Thread.sleep(c.getNotAfter().getTime() - System.currentTimeMillis() + 1500);
        try (javax.net.ssl.SSLSocket s = (javax.net.ssl.SSLSocket) f.createSocket("localhost", b.port())) {
            s.startHandshake();
            javax.net.ssl.SSLSession second = s.getSession();
            System.out.println("LP second " + second.getProtocol() + " created " + second.getCreationTime()
                    + " sameId " + java.util.Arrays.equals(first.getId(), second.getId())
                    + " peerNotAfter " + ((X509Certificate) second.getPeerCertificates()[0]).getNotAfter()
                    + " now " + new java.util.Date());
