        ExecutorService pool = Executors.newFixedThreadPool(16);
        try {
            List<Future<Integer>> fs = new ArrayList<>();
            for (int i = 0; i < 48; i++) {
                fs.add(pool.submit(new Callable<Integer>() {
                    @Override
                    public Integer call() {
                        return get().status();
                    }
                }));
            }
            for (Future<Integer> f : fs) {
